import{z as i,x as A,o as t,c as d,q as s,j as n,D as o,d as E,s as r,S as C,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"分组模式 CBC / GCM","description":"","frontmatter":{"title":"分组模式 CBC / GCM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/block-modes.md","filePath":"cs/block-modes.md","lastUpdated":1791063341000}'),B={name:"cs/block-modes.md"};function p(c,a,m,D,h,u){const l=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="分组模式-cbc-gcm" tabindex="-1">分组模式 CBC / GCM <a class="header-anchor" href="#分组模式-cbc-gcm" aria-label="Permalink to &quot;分组模式 CBC / GCM&quot;">​</a></h1><div class="epigraph"><p>分组密码只加密定长块；CBC 用链式 IV 扩到消息，GCM 再把保密与完整性收成一次 AEAD。</p><footer>—— 据 NIST 对 CBC 与 GCM；Stallings；Anderson 对「只加密不够」的整理</footer></div><p><a href="/cs/symmetric-crypto">上一课</a>给出共享密钥下的语义安全直觉。本课不重定义「不可区分」。缺口是工作模式：ECB 泄露相等块；CBC 需要不可预测 IV；仅加密不防篡改。<a href="/cs/dolev-yao">Dolev–Yao</a> 的理想锁在真实模式选错时并不成立。公钥信封下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对称课留下「工作模式」。消息长度不是一块。CBC：IV 异或后链式，解密可并行。缺完整性时，密文被改可能变成对明文的可控差异——本课只陈述性质与防御：必须另加 MAC 或改用 AEAD。GCM：CTR 保密 + GHASH 认证，IV 不得复用。缺口是<strong>模式如何兑现 C 与 I</strong>。</p><p><span class="marginnote">IV/nonce 复用是规格失败，不是「算法过时」。防御是随机 IV、唯一 nonce、或协议层禁止重用。不给构造步骤。</span></p><p><span class="marginnote">数字实例：AES 一块只有 16 字节。ECB 模式逐块独立加密，加密一张图片时相同颜色的块得到相同密文块，企鹅的轮廓仍然可见——这正是「分组密码只加密定长块、模式决定安全」最著名的一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>只保密：CBC + 独立 MAC（Encrypt-then-MAC）是经典组合。优先 AEAD（GCM 等）：一次密钥、一次 nonce、密文带认证标签。TLS 1.3 只保留 AEAD 套件（后课 RFC 8446）。本课不比较全部厂商模式缩写。</p>',9)),(t(),n(C,null,{default:o(()=>[r(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E5%88%86%E7%BB%84%E5%AF%86%E7%A0%81%22%5D%20--%3E%20CBC%5B%22CBC%20%E9%93%BE%E5%BC%8F%20%2B%20IV%22%5D%0A%20%20BLK%20--%3E%20GCM%5B%22GCM%3A%20CTR%20%E5%8A%A0%20GHASH%22%5D%0A%20%20CBC%20--%3E%20MAC%5B%22%E4%BB%8D%E9%9C%80%E7%8B%AC%E7%AB%8B%E5%AE%8C%E6%95%B4%E6%80%A7%22%5D%0A%20%20GCM%20--%3E%20AEAD%5B%22%E4%B8%80%E6%AC%A1%E7%BB%99%E5%87%BA%20C%20%E4%B8%8E%20I%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：AEAD 就是「带认证的加密」——一个函数同时做两件事：把明文变密文（保密），并附一个认证标签（完整性）。解密时先验标签，对不上直接报错丢弃，根本不会输出「可能被改过」的明文。GCM 是它的事实标准。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"模式把块函数变成消息函数。完整性失败会让 DY 敌手「改项仍被当成合法密文」，理想锁破产。IV 是状态，不是密钥，但必须按模式合同使用。后课公钥只运这把对称键，大数据仍走本课 AEAD。",-1)),a[6]||(a[6]=e("p",null,"CBC 的「链」具体怎么一环扣一环，值得单独画。",-1)),(t(),n(C,null,{default:o(()=>[r(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20P1%5B%22%E6%98%8E%E6%96%87%E5%9D%97%201%22%5D%20--%3E%20XOR1%5B%22%E4%B8%8E%20IV%20%E5%BC%82%E6%88%96%22%5D%0A%20%20XOR1%20--%3E%20E1%5B%22%E5%8A%A0%E5%AF%86%22%5D%0A%20%20E1%20--%3E%20C1%5B%22%E5%AF%86%E6%96%87%E5%9D%97%201%22%5D%0A%20%20C1%20--%3E%20XOR2%5B%22%E4%B8%8E%E6%98%8E%E6%96%87%E5%9D%97%202%20%E5%BC%82%E6%88%96%22%5D%0A%20%20P2%5B%22%E6%98%8E%E6%96%87%E5%9D%97%202%22%5D%20--%3E%20XOR2%0A%20%20XOR2%20--%3E%20E2%5B%22%E5%8A%A0%E5%AF%86%22%5D%0A%20%20E2%20--%3E%20C2%5B%22%E5%AF%86%E6%96%87%E5%9D%97%202%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：以为「加了密就不会被篡改」。只加密不认证时，敌手翻转密文里的一个比特，解密端会老老实实输出被改动的明文——保密与完整性是两根轴。另一条红线：GCM 的 nonce 复用一次就足以同时毁掉保密和认证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入填充预言的操作细节，不把任何利用链写成可复现步骤。第一次见面如何分发密钥，下一课公钥与信封。</p><p>后课默认：长消息用 AEAD。密钥分发用公钥封装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CBC 扩块；单独加密不给完整性。</li><li>GCM 一类 AEAD 同时服务 C 与 I。</li><li>公钥信封下一课。</li><li>出处：NIST 模式；Stallings；Anderson。</li></ul>',6))])}const b=i(B,[["render",p]]);export{_ as __pageData,b as default};
